import json

# Load the JSON data
with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# The table is in multiple page elements, let's find all related to "Average Yields"
# Search for elements that have the text we need
def find_elements_with_text(element, text_to_find):
    results = []
    if element.get('content') and text_to_find in element.get('content'):
        results.append(element)
    if 'elements' in element:
        for child in element.get('elements', []):
            results.extend(find_elements_with_text(child, text_to_find))
    return results

# Search for page that has the table
for el in data.get('document', {}).get('elements', []):
    if el.get('type') == 'table':
        content = el.get('content', '')
        if 'Treasury bonds' in content and 'Aa new corporate' in content:
            # Check for year headers
            if '196' in content:
                print("Found table with years!")
                print(content[:3000])
                break
